/// <summary>
/// The <c>AVAWhsSplitWorkCls_Extension</c> represents a extension of WhsSplitWork table.
/// </summary>
/// <remarks>
/// AVA_6726_8001_RFFull_WorkLockMode
/// </remarks>
[
    ExtensionOf(classStr(WhsSplitWork))
]
final class AVAWhsSplitWorkCls_Extension
{
}

Method.Source:
/// <summary>
/// Initializes the original work header for update.
/// </summary>
/// <param name = "_workTable">The work header record.</param>
protected void initializeOriginalWorkTableForUpdate(WHSWorkTable _workTable)
{
    AVAWorkFullModeIDisposable   avaAVAWorkFullModeIDisposable;

    next initializeOriginalWorkTableForUpdate(_workTable);

    avaAVAWorkFullModeIDisposable = AVAWorkFullModeIDisposable::current();

    if (avaAVAWorkFullModeIDisposable
        && avaAVAWorkFullModeIDisposable.workFullLockMode == NoYes::Yes)
    {
        _workTable.Frozen = NoYes::Yes;
    }
}

/// <summary>
/// chaon of command of splitWork
/// </summary>
/// <returns>
/// the retun value of splitWork
/// </returns>
public WHSWorkId splitWork()
{
    WHSWorkId                   workId;
    AVAWorkFullModeIDisposable  avaAVAWorkFullModeIDisposable;

    avaAVAWorkFullModeIDisposable = AVAWorkFullModeIDisposable::current();

    using (AVAWhsSplitWorkProcessIDisposable instance = AVAWhsSplitWorkProcessIDisposable::construct())
    {
        workId = next splitWork();

        if (avaAVAWorkFullModeIDisposable
         && workId)
        {
            avaAVAWorkFullModeIDisposable.finishedSplit = true;
        }
    }

    return workId;
}
